import type { VideoStreamType } from '../lib/Video';
export type RegisterVideoEvent = {
    args: {
        type: VideoStreamType;
        options: Record<string, unknown>;
    };
    return: {
        id: string;
        type: VideoStreamType;
    };
};
export type UnregisterVideoEvent = {
    args: {
        id: string;
    };
    return: void;
};
export type OnVideoOfferEvent = {
    args: {
        id: string;
        offer: string;
    };
    return: unknown;
};
export type OnVideoKeepAliveEvent = {
    args: {
        id: string;
        streamId: string;
    };
    return: unknown;
};
export type OnVideoUrlEvent = {
    args: {
        id: string;
    };
    return: unknown;
};
export type HomeyVideoEvents = {
    onVideoOffer: OnVideoOfferEvent;
    onVideoKeepAlive: OnVideoKeepAliveEvent;
    onVideoUrl: OnVideoUrlEvent;
};
export type SDKVideoEvents = {
    registerVideo: RegisterVideoEvent;
    unregisterVideo: UnregisterVideoEvent;
};
export type VideoClient = {
    emit: (event: string, args: unknown) => Promise<unknown>;
};
